def meldinger_per_bydel(tabell):
    k = tabell[0].index('bydel')
    d = {}
    for rad in tabell[1:]:
        d[rad[k]] = d.get(rad[k], 0) + 1
    return d

def dager_per_bydel(tabell):
    k_bydel = tabell[0].index('bydel')
    k_dager = tabell[0].index('dager')
    d = {}
    for rad in tabell[1:]:
        d[rad[k_bydel]] = d.get(rad[k_bydel], 0) + rad[k_dager]
    return d

tabell = [['bydel', 'type', 'dager'], ['Nordre', 'veilys', 4],
          ['Sentrum', 'hull i vei', 11], ['Nordre', 'hull i vei', 6],
          ['Ostre', 'soppelspann', 2], ['Sentrum', 'veilys', 3],
          ['Nordre', 'veilys', 9]]
print(meldinger_per_bydel(tabell))
print(dager_per_bydel(tabell))
```

**Utskrift:**
```
{'Nordre': 3, 'Sentrum': 2, 'Ostre': 1}
{'Nordre': 19, 'Sentrum': 14, 'Ostre': 2}
```

Nordre har tre meldinger og 19 dager til sammen; Sentrum har to og 14; Østre har én og 2.

**Neste steg, som en deloppgave gjerne ber om:** gjennomsnittlig behandlingstid per bydel er den ene ordboka delt på den andre:

```python
antall = {'Nordre': 3, 'Sentrum': 2, 'Ostre': 1}
dager = {'Nordre': 19, 'Sentrum': 14, 'Ostre': 2}
snitt = {}
for bydel in antall:
    snitt[bydel] = dager[bydel] / antall[bydel]
print(snitt)
```

**Utskrift:**
```
{'Nordre': 6.333333333333333, 'Sentrum': 7.0, 'Ostre': 2.0}
```

Det er derfor de to ordbøkene er verdt å bygge hver for seg: sammen svarer de på et tredje spørsmål ingen av dem svarer på alene.
